def power(base, exp=2):
    return base ** exp

def total(*numbers):
    return sum(numbers)

def profile(**info):
    return ", ".join(f"{k}={v}" for k, v in info.items())

print(power(5), power(2, 8), power(exp=3, base=2))
print(total(1, 2, 3, 4))
print(profile(name="Ali", age=20))

class Student:
    def __init__(self, name, marks):
        self.name = name
        self.marks = marks

    def passed(self):
        return self.marks >= 50

a = Student("Ayesha", 82)
b = Student("Bilal", 41)
print(a.name, a.passed())
print(b.name, b.passed())

class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __str__(self):
        return f"Point({self.x}, {self.y})"

    def __add__(self, other):
        return Point(self.x + other.x, self.y + other.y)

p = Point(1, 2) + Point(3, 4)
print(p)

class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return "..."

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)
        self.breed = breed
    def speak(self):
        return "Woof"

class Cat(Animal):
    def speak(self):
        return "Meow"

for pet in [Dog("Rex", "Husky"), Cat("Tom")]:
    print(pet.name, "says", pet.speak())

def to_number(text):
    try:
        return int(text)
    except ValueError:
        print(f"{text!r} is not a number")
        return None
    finally:
        print("checked", repr(text))

print(to_number("42"))
print(to_number("abc"))

